{
  "status": "issues",
  "checks": [
    "claim_scope",
    "numeric_bounds"
  ],
  "issues": [
    {
      "category": "scope_expansion",
      "claim_path": "/chapter_plan/thesis",
      "claim_quote": "现有文献中广泛使用的效率指标（如全孔径平均值）和成像质量评价标准（如 FWHM）存在系统性偏差，掩盖了高数值孔径下边缘区域的严重性能衰减",
      "problem": "主张声称‘广泛使用’的指标存在‘系统性偏差’并‘掩盖’了衰减。然而，证据 P0001 仅针对 Kho16 等特定案例指出其报告的是‘全孔径平均值’且未区分绝对/相对效率，并建议未来应更多采用 MTF。证据并未证明整个领域‘广泛使用’这些指标构成了‘系统性偏差’，也未证实这些指标在所有情况下都‘掩盖’了性能衰减（例如 Lal99 的研究就关注了角度稳定性）。该主张将针对特定研究的批评泛化为整个领域的系统性问题，超出了证据支持的范围。",
      "requested_change": "将‘广泛使用...存在系统性偏差’修改为更具体的表述，如‘部分高 NA 研究（如 Kho16）中使用的效率指标（如全孔径平均值）和评价标准（如 FWHM）可能无法充分反映边缘区域的性能衰减’，并移除‘系统性偏差’这一缺乏全域证据的定性描述。",
      "evidence": [
        {
          "path": "/source_materials/0/study_summary_A/key_findings/4",
          "quote": "Compares experimental efficiencies of high-NA metalenses (e.g., Kho16) with historical blazed-binary elements (Lal99). Notes that while absolute efficiency is high (~86%), characterization methods (like MTF and sidelobe analysis) reveal departures from diffraction-limited performance."
        },
        {
          "path": "/source_materials/0/deep_read_material/question_material/5/examples/0/finding",
          "quote": "[Kho16] reported the focal spot FWHM, but the authors note that since sidelobes are enhanced and the MTF departs from that of a diffraction limited lens, FWHM alone is not sufficient to characterize diffraction-limited operation..."
        }
      ]
    },
    {
      "category": "numeric_bound",
      "claim_path": "/chapter_plan/units/1/ordered_development/0/development",
      "claim_quote": "对于 NA=0.5、焦距 1mm 的透镜，在可见光范围内路径延迟误差不超过一个波长的低像差视场被严格限制在小于 5 µm。",
      "problem": "主张中的数值边界‘小于 5 µm’与证据一致，但主张将其描述为‘严格限制’（strictly limited），暗示这是一个绝对的物理硬边界。证据 P0001 明确指出这是基于‘路径延迟误差不超过一个波长’这一特定像质评价标准下的估算值（estimate/calculation example），而非不可逾越的物理极限。若放宽像差容忍度，视场可以更大。将特定标准下的估算值表述为‘严格限制’混淆了工程标准与物理极限。",
      "requested_change": "将‘被严格限制在’修改为‘在路径延迟误差不超过一个波长的标准下，被限制在’或‘估算表明...被限制在’，以明确该数值边界依赖于特定的像差容忍标准，而非绝对的物理截止。",
      "evidence": [
        {
          "path": "/source_materials/0/study_summary_A/key_findings/1",
          "quote": "For NA=0.5, the low-aberration field of view is restricted to less than 5 µm in the visible range, making single-element metalenses unsuitable for high-performance wide-field imaging compared to multi-element objectives."
        },
        {
          "path": "/source_materials/0/deep_read_material/question_material/8/examples/0/finding",
          "quote": "For a numerical aperture NA=0.5, focal length f=1mm single-interface lens, in the visible range, if the path delay error is required not to exceed one wavelength (i.e. low aberration range), its field of view is restricted to less than 5 µm."
        }
      ]
    },
    {
      "category": "scope_expansion",
      "claim_path": "/chapter_plan/units/2/ordered_development/0/development",
      "claim_quote": "这一极小的视场意味着单界面透镜适用于点对点互连，但不适用于高性能成像。",
      "problem": "主张断言单界面透镜‘不适用于高性能成像’。证据 P0001 的原文是‘不适合高性能宽视场成像’（unsuitable for high-performance wide-field imaging）或‘不适用于高性能成像应用’（但在上下文中特指大视场）。证据承认其在小视场（<5 µm）下可以是低像差的。完全排除‘高性能成像’的可能性忽略了其在极小视场下可能达到的衍射极限性能（即点对点或小视场高分辨率成像也是高性能成像的一种）。主张的范围比证据支持的更广。",
      "requested_change": "将‘不适用于高性能成像’修改为‘不适用于高性能宽视场成像’或‘限制了其在需要大视场的高性能成像中的应用’，以准确反映证据中关于视场大小限制的核心论点。",
      "evidence": [
        {
          "path": "/source_materials/0/study_summary_A/key_findings/1",
          "quote": "For NA=0.5, the low-aberration field of view is restricted to less than 5 µm in the visible range, making single-element metalenses unsuitable for high-performance wide-field imaging compared to multi-element objectives."
        },
        {
          "path": "/source_materials/0/deep_read_material/question_material/8/explanation",
          "quote": "This extremely small field of view means that single-interface lenses are suitable for point-to-point interconnects, but not for high-performance imaging applications."
        }
      ]
    }
  ]
}

